import { NextResponse, type NextRequest } from "next/server";
import { promises as fsp } from "node:fs";
import { db } from "@/lib/db";
import { thumbnailPath } from "@/lib/downloader/engine";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** GET /api/downloads/:id/thumb - JPEG thumbnail generated by ffmpeg. */
export async function GET(_req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const job = await db.download.findUnique({ where: { id }, select: { hasThumbnail: true } });
  if (!job || !job.hasThumbnail) {
    return NextResponse.json({ error: "No thumbnail available." }, { status: 404 });
  }
  try {
    const data = await fsp.readFile(thumbnailPath(id));
    return new Response(new Uint8Array(data), {
      status: 200,
      headers: {
        "Content-Type": "image/jpeg",
        "Cache-Control": "private, max-age=86400",
      },
    });
  } catch {
    return NextResponse.json({ error: "Thumbnail file missing." }, { status: 404 });
  }
}
